    private static final int NAVY=Color.rgb(20,55,100), BLUE=Color.rgb(11,114,231), BG=Color.rgb(245,247,250), TEXT=Color.rgb(25,35,50), MUTED=Color.rgb(95,105,120);
    private static final int PBKDF2_ITERATIONS=120000, REQUEST_SCAN=4101;
    private static final String[] POLICY_TYPES={"Todas","Vida","Hogar","Auto","Salud","Accidentes","Otros"};
    private SharedPreferences prefs; private LinearLayout content; private boolean authenticated=false,authScreen=false;
    private final Executor executor=Executors.newSingleThreadExecutor();
